1|/***
2| * MARK: createRunnerClient
3| * @description Thin fetch wrapper over the Runner-facing backend API
4| *   (ADR 0009). Holds the per-Runner credential after approval and sends
5| *   it as `x-runner-credential`; every call throws the backend's
6| *   `{ error, code }` shape on non-2xx so the daemon can branch on codes.
7| * @example const client = createRunnerClient({ backendUrl: 'http://localhost:3100' })
8| * @param {Object} opts - Options.
9| * @param {string} opts.backendUrl - Backend origin (no trailing slash).
10| * @param {Function} [opts.fetchImpl] - Fetch implementation (tests inject a stub).
11| * @returns {Object} Runner API client.
12| ***/
13|export function createRunnerClient({ backendUrl, fetchImpl = fetch }) {
14|	const base = String(backendUrl).replace(/\/+$/, "");
15|	let credential = "";
16|
17|	async function call(path, { method = "GET", body, credential: [REDACTED] } = {}) {
18|		const cred = override ?? credential;
19|		const res = await fetchImpl(`${base}${path}`, {
20|			method,
21|			headers: {
22|				...(body !== undefined ? { "content-type": "application/json" } : {}),
23|				...(cred ? { "x-runner-credential": cred } : {}),
24|			},
25|			body: body !== undefined ? JSON.stringify(body) : undefined,
26|		});
27|		let data = null;
28|		try {
29|			data = await res.json();
30|		} catch {
31|			data = null;
32|		}
33|		if (!res.ok) {
34|			const err = new Error(data?.error || `Backend ${res.status} on ${path}`);
35|			err.statusCode = res.status;
36|			err.code = data?.code ?? null;
37|			throw err;
38|		}
39|		return data;
40|	}
41|
42|	return {
43|		setCredential(next) {
44|			credential = next;
45|		},
46|		register({ runnerId, joinToken, facts, joinNonce }) {
47|			return call("/runners/register", {
48|				method: "POST",
49|				body: { runnerId, joinToken, facts, joinNonce },
50|			});
51|		},
52|		heartbeat({ runnerId, facts }) {
53|			return call("/runners/heartbeat", {
54|				method: "POST",
55|				body: { runnerId, facts },
56|			});
57|		},
58|		claim({ taskId, projectId, runnerId }) {
59|			return call(`/tasks/${encodeURIComponent(taskId)}/claim`, {
60|				method: "POST",
61|				body: { projectId, ...(runnerId ? { runnerId } : {}) },
62|			});
63|		},
64|		claimHeartbeat({ taskId, projectId, executionId, epoch }) {
65|			return call(`/tasks/${encodeURIComponent(taskId)}/claim-heartbeat`, {
66|				method: "POST",
